def amort(p,r,years,months=None):
 i=r/12;n=years*12;a=p*i/(1-(1+i)**-n) if i else p/n;k=months if months is not None else n;b=p;ints=0
 for _ in range(k):it=b*i;ints+=it;b+=it-a
 closed=p*(1+i)**k-a*((1+i)**k-1)/i if i else p-a*k
 assert abs(b-closed)<1e-5
 return dict(monthly_payment=a,months=k,total_payments=a*k,interest_paid=ints,principal_repaid=p-b,balance=max(0,b))
